#include <stdarg.h>
#include <stdio.h>

static void warn(const char *format, ...) {
    va_list args;
    va_start(args, format);
    fputs("warning: ", stderr);
    vfprintf(stderr, format, args);
    va_end(args);
}

int main(void) {
    warn("%d files skipped\n", 3);
    return 0;
}

#include <stdarg.h>
#include <stdio.h>

static int read_values(FILE *f, const char *format, ...) {
    va_list args;
    va_start(args, format);
    int n = vfscanf(f, format, args);
    va_end(args);
    return n;
}

int main(void) {
    int a, b;
    if (read_values(stdin, "%d %d", &a, &b) == 2) {
        printf("%d\n", a + b);
    }
    return 0;
}

