#include <stdarg.h>
#include <stdio.h>

static int format_label(char *out, size_t size, const char *format, ...) {
    va_list args;
    va_start(args, format);
    int needed = vsnprintf(out, size, format, args);
    va_end(args);
    return needed;
}

int main(void) {
    char label[16];
    if (format_label(label, sizeof label, "%s:%d", "line", 42) < (int)sizeof label) {
        puts(label);
    }
    return 0;
}

