}

#include <stdarg.h>
#include <stdio.h>

static int parse(const char *text, const char *format, ...) {
    va_list args;
    va_start(args, format);
    int n = vsscanf(text, format, args);
    va_end(args);
    return n;
}

int main(void) {
    int major, minor;
    if (parse("1.4", "%d.%d", &major, &minor) == 2) {
        printf("major %d, minor %d\n", major, minor);
    }
    return 0;
}
